#!/usr/bin/env python3
"""Pack the buddy poses into a header the firmware can blit.

    python make-buddy-frames.py <dir with idle.bin ...> > buddy_frames.h

The .bin frames are 400x300, one bit per pixel, MSB first, 1 = black — the same
layout as GFXcanvas1, so the firmware copies a frame straight into the canvas.
"""

import pathlib
import sys

POSES = ["idle", "idle_b", "happy", "sleeping", "confused", "error"]
BYTES = 400 * 300 // 8


def main():
    if len(sys.argv) != 2:
        print(__doc__)
        return 1
    src = pathlib.Path(sys.argv[1])
    out = [
        "// Generated by tools/make-buddy-frames.py; do not edit.",
        "// 400x300, 1 bit per pixel, MSB first, 1 = black (GFXcanvas1 layout).",
        "#pragma once",
        "#include <stdint.h>",
        "",
    ]
    for pose in POSES:
        path = src / f"{pose}.bin"
        if not path.exists():
            print(f"missing {path}", file=sys.stderr)
            return 1
        data = path.read_bytes()
        if len(data) != BYTES:
            print(f"{path}: {len(data)} bytes, expected {BYTES}", file=sys.stderr)
            return 1
        out.append(f"static const uint8_t buddy_{pose}[{BYTES}] PROGMEM = {{")
        for i in range(0, BYTES, 16):
            chunk = ", ".join(f"0x{b:02X}" for b in data[i:i + 16])
            out.append(f"  {chunk},")
        out.append("};")
        out.append("")
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
